import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
const off = new SuperJSON({errorStack:{mode:'off'}}); off.allowErrorProps('stack'); assert.ok(!('stack' in off.serialize(new Error('test')).json));
const s = new SuperJSON({errorStack:{mode:'frames',normalizeNewlines:true,stripInternalFrames:'node',includeCauses:'deep',sanitizeMessage:true}}); s.allowErrorProps('stackFrames'); const e = new Error('contact a@b.com',{cause:new Error('see https://example.com')}); e.stack='Error: test\r\n  at node:internal/foo\r\n  at /app/file.js:1:2'; const serialized=s.serialize(new Map([['error',e]])); const restored=s.deserialize(serialized).get('error'); assert.equal(restored.message,'contact [redacted]'); assert.equal(restored.cause.message,'see [redacted]'); assert.deepEqual(restored.stackFrames,[{raw:'Error: test'},{raw:'at /app/file.js:1:2'}]); console.log('Feature smoke checks passed');
EOF
